using System;using System.IO;using UnityEngine;using UnityEngine.Video;using UnityEditor;
[InitializeOnLoad]public static class CityMovieCheck{static VideoPlayer p;static int n;static double started;static readonly double[] times={3.75,18.75,26.25,63.75,71.25,101.25,116.25};static CityMovieCheck(){EditorApplication.update+=Tick;}static void Tick(){if(EditorApplication.isCompiling)return;if(!p){if(!File.Exists("CityMovieCheck.request"))return;File.Delete("CityMovieCheck.request");var go=new GameObject("Temporary MP4 playback check"){hideFlags=HideFlags.HideAndDontSave};p=go.AddComponent<VideoPlayer>();p.url=Path.GetFullPath("CityCinematicV3/Gangstar-City-Cinematic-1080p.mp4");p.renderMode=VideoRenderMode.APIOnly;p.audioOutputMode=VideoAudioOutputMode.None;p.sendFrameReadyEvents=true;p.frameReady+=Frame;p.errorReceived+=(v,e)=>{File.WriteAllText("CityCinematicV3/PlaybackCheck.txt",e);UnityEngine.Object.DestroyImmediate(v.gameObject);};n=0;started=EditorApplication.timeSinceStartup;p.prepareCompleted+=v=>{v.time=times[0];v.Play();};p.Prepare();}if(p&&EditorApplication.timeSinceStartup-started>60){File.WriteAllText("CityCinematicV3/PlaybackCheck.txt","Playback check timed out");UnityEngine.Object.DestroyImmediate(p.gameObject);}}static void Frame(VideoPlayer v,long f){if(n>=times.Length||Math.Abs(v.time-times[n])>.3)return;v.Pause();var rt=RenderTexture.GetTemporary(960,540);Graphics.Blit(v.texture,rt);var old=RenderTexture.active;RenderTexture.active=rt;var tex=new Texture2D(960,540,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,960,540),0,0);tex.Apply();File.WriteAllBytes("CityCinematicV3/VideoCheck-"+times[n]+".png",tex.EncodeToPNG());UnityEngine.Object.DestroyImmediate(tex);RenderTexture.active=old;RenderTexture.ReleaseTemporary(rt);n++;if(n==times.Length){File.WriteAllText("CityCinematicV3/PlaybackCheck.txt","SUCCESS decoded MP4 frames at 3.75,18.75,26.25,63.75,71.25,101.25,116.25 seconds. Duration="+v.length+" size="+v.width+"x"+v.height+" fps="+v.frameRate+" audioTracks="+v.audioTrackCount);EditorApplication.delayCall+=()=>UnityEngine.Object.DestroyImmediate(v.gameObject);}else {v.time=times[n];v.Play();}}}
